param(
    [string]$Stage = "",
    [string]$OutputDirectory = "dist/msix",
    [ValidateSet("Review", "Store", "Signed")][string]$Mode = "Review",
    [string]$IdentityFile,
    [string]$Version = "",
    [string]$CertificateThumbprint = $env:CHIMERA_SIGNING_THUMBPRINT
)
$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest
$identityJson = & python (Join-Path $PSScriptRoot "chimera_version.py")
if ($LASTEXITCODE -ne 0) { throw "Cannot resolve the source product version." }
$buildIdentity = $identityJson | ConvertFrom-Json
if (!$Stage) { $Stage = "dist/SpectralForge-Chimera-$($buildIdentity.version)-win64" }
if (!$Version) { $Version = "$($buildIdentity.product_version).0" }
if ($Version -cne "$($buildIdentity.product_version).0") { throw "MSIX version differs from source product version." }
$publisherDisplayName = "RavenForge Luthier Intelligence"
$packageName = "RavenForge.ChimeraAmpMatrix.Review"
$publisher = "CN=$publisherDisplayName"
if ($Version -notmatch '^[1-9][0-9]*\.[0-9]+\.[0-9]+\.0$' -or
    @($Version.Split('.') | Where-Object { [long]$_ -gt 65535 }).Count) {
    throw "Use a four-part MSIX version with values <= 65535 and the Store-reserved last part 0."
}
if ($Mode -eq "Store") {
    if (!$IdentityFile -or !(Test-Path -LiteralPath $IdentityFile -PathType Leaf)) {
        throw "Store packaging requires the real Partner Center identity JSON; no Store identity has been assumed."
    }
    $identity = Get-Content -LiteralPath $IdentityFile -Raw | ConvertFrom-Json
    foreach ($field in @("Name", "Publisher", "PublisherDisplayName")) {
        if (!$identity.PSObject.Properties[$field] -or [string]::IsNullOrWhiteSpace($identity.$field)) {
            throw "Partner Center identity JSON is missing $field."
        }
    }
    $packageName = [string]$identity.Name
    $publisher = [string]$identity.Publisher
    if ([string]$identity.PublisherDisplayName -cne $publisherDisplayName) {
        throw "Partner Center PublisherDisplayName must match the requested RavenForge publisher; resolve the account identity before packaging."
    }
    if ($packageName -eq "RavenForge.ChimeraAmpMatrix.Review" -or $publisher -notmatch '^CN=') {
        throw "Use the exact package Name and Publisher copied from Partner Center."
    }
}
if ($Mode -eq "Signed") {
    if ($CertificateThumbprint -notmatch '^[0-9A-Fa-f]{40}$') { throw "Direct MSIX distribution requires a verified public code-signing certificate." }
    $certificate = Get-Item -LiteralPath "Cert:/CurrentUser/My/$CertificateThumbprint"
    $publisher = $certificate.Subject
    $packageName = "RavenForge.ChimeraAmpMatrix"
}
if ($packageName -notmatch '^[A-Za-z0-9.-]{3,50}$') { throw "Package identity Name has invalid characters or length." }
$stagePath = (Resolve-Path -LiteralPath $Stage).Path
$executable = Join-Path $stagePath "Standalone/SpectralForge Chimera.exe"
if (!(Test-Path -LiteralPath $executable -PathType Leaf)) { throw "Validated standalone executable is missing." }
$command = Get-Command MakeAppx.exe -ErrorAction SilentlyContinue
$makeAppx = if ($command) { $command.Source } else {
    Get-ChildItem -Path "${env:ProgramFiles(x86)}/Windows Kits/10/bin/*/x64/makeappx.exe" -ErrorAction SilentlyContinue |
        Sort-Object FullName -Descending | Select-Object -First 1 -ExpandProperty FullName
}
if (!$makeAppx) { throw "Windows SDK MakeAppx.exe is required." }
New-Item -ItemType Directory -Force -Path $OutputDirectory | Out-Null
$outputPath = (Resolve-Path -LiteralPath $OutputDirectory).Path
$work = Join-Path ([IO.Path]::GetTempPath()) ("Chimera-MSIX-" + [guid]::NewGuid().ToString("N"))
New-Item -ItemType Directory -Path "$work/App", "$work/Assets", "$work/Docs" -Force | Out-Null
try {
    Copy-Item -LiteralPath $executable -Destination "$work/App/SpectralForge Chimera.exe"
    Copy-Item -LiteralPath (Join-Path $PSScriptRoot "../COPYRIGHT.txt") -Destination "$work/Docs/COPYRIGHT.txt"
    foreach ($name in @("MANUAL.html", "OPEN_BETA_RELEASE_NOTES.md", "INSTALLATION.md", "THIRD_PARTY_NOTICES.md", "AMP_VALIDATION.md", "MODELS_AND_REFERENCE.md", "NAM_REFERENCE_RESULTS.md", "WINDOWS_MSIX.md")) {
        Copy-Item -LiteralPath (Join-Path $PSScriptRoot "../docs/$name") -Destination "$work/Docs/$name"
    }
    # Raster resampling only: use the same generated RavenForge emblem as the app.
    Add-Type -AssemblyName System.Drawing
    $art = [Drawing.Image]::FromFile((Resolve-Path -LiteralPath (Join-Path $PSScriptRoot "../Assets/Artwork/spectralforge-emblem.png")))
    try {
        foreach ($logo in @(@("Square150x150Logo.png",150), @("Square44x44Logo.png",44), @("StoreLogo.png",50))) {
            $bitmap = [Drawing.Bitmap]::new([int]$logo[1], [int]$logo[1])
            $graphics = [Drawing.Graphics]::FromImage($bitmap)
            try {
                $graphics.Clear([Drawing.Color]::Transparent)
                $graphics.InterpolationMode = [Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
                $graphics.DrawImage($art, 0, 0, [int]$logo[1], [int]$logo[1])
                $bitmap.Save((Join-Path "$work/Assets" $logo[0]), [Drawing.Imaging.ImageFormat]::Png)
            } finally { $graphics.Dispose(); $bitmap.Dispose() }
        }
    } finally { $art.Dispose() }
    [xml]$manifest = Get-Content -LiteralPath (Join-Path $PSScriptRoot "../Installer/MSIX/AppxManifest.xml") -Raw
    $manifest.Package.Identity.SetAttribute("Name", $packageName)
    $manifest.Package.Identity.SetAttribute("Publisher", $publisher)
    $manifest.Package.Identity.SetAttribute("Version", $Version)
    $manifest.Save("$work/AppxManifest.xml")
    $suffix = if ($Mode -eq "Store") { "store-submission" } elseif ($Mode -eq "Signed") { "signed" } else { "review-unsigned" }
    $package = Join-Path $outputPath "Chimera-$Version-x64-$suffix.msix"
    if ($Mode -eq "Signed") {
        & (Join-Path $PSScriptRoot "Sign-WindowsArtifact.ps1") -Path "$work/App/SpectralForge Chimera.exe" -CertificateThumbprint $CertificateThumbprint -ExpectedPublisher $publisherDisplayName
    }
    & $makeAppx pack /d $work /p $package /h SHA256 /o
    if ($LASTEXITCODE -ne 0) { throw "MakeAppx schema/semantic validation or packaging failed." }
    if ($Mode -eq "Signed") {
        & (Join-Path $PSScriptRoot "Sign-WindowsArtifact.ps1") -Path $package -CertificateThumbprint $CertificateThumbprint -ExpectedPublisher $publisherDisplayName
    }
    $hash = (Get-FileHash -LiteralPath $package -Algorithm SHA256).Hash.ToLowerInvariant()
    "$hash  $([IO.Path]::GetFileName($package))" | Set-Content -LiteralPath ($package + ".sha256.txt")
    Copy-Item -LiteralPath "$work/AppxManifest.xml" -Destination (Join-Path $outputPath "AppxManifest.xml")
    Copy-Item -LiteralPath (Join-Path $PSScriptRoot "../docs/WINDOWS_MSIX.md") -Destination $outputPath
    Write-Host "MSIX created: $package | mode=$Mode | publisher=$publisherDisplayName"
    if ($Mode -eq "Review") { Write-Host "REVIEW ONLY: unsigned and not Store-certified; not a customer-installable release." }
    if ($Mode -eq "Store") { Write-Host "Submit through the matching Partner Center app. Microsoft signs only after certification." }
} finally {
    # Only this invocation's randomly named temporary staging directory.
    Remove-Item -LiteralPath $work -Recurse -Force
}

param(
    [Parameter(Mandatory = $true)][string[]]$Path,
    [string]$ReportDirectory = "build/windows-security"
)
$ErrorActionPreference = "Stop"
$PSNativeCommandUseErrorActionPreference = $false
Set-StrictMode -Version Latest
if ($env:GITHUB_ACTIONS -ne "true" -or !$IsWindows) {
    throw "This scan is restricted to disposable Windows GitHub runners."
}
New-Item -ItemType Directory -Force -Path $ReportDirectory | Out-Null
$reportRoot = (Resolve-Path -LiteralPath $ReportDirectory).Path
$reportFile = Join-Path $reportRoot "WindowsSecurity.txt"
$lines = [Collections.Generic.List[string]]::new()
function Note([string]$Message) {
    $lines.Add($Message)
    Write-Host $Message
    $lines | Set-Content -LiteralPath $reportFile -Encoding utf8
}
function Defender-Command([string[]]$Arguments, [string]$LogName) {
    $output = & $script:mpCmdRun @Arguments 2>&1
    $result = $LASTEXITCODE
    $output | Set-Content -LiteralPath (Join-Path $reportRoot $LogName) -Encoding utf8
    $output | ForEach-Object { Write-Host "$_" }
    return $result
}
function Update-DefenderIntelligence {
    # Fixed bounded policy; no fallback to stale definitions or skipped scans.
    $attempts = [Collections.Generic.List[object]]::new()
    for ($attempt = 1; $attempt -le 3; ++$attempt) {
        $logName = "SignatureUpdate-$attempt.log"
        $started = [DateTime]::UtcNow.ToString('o')
        $exitCode = $null
        $errorMessage = $null
        try { $exitCode = Defender-Command @("-SignatureUpdate", "-MMPC") $logName }
        catch { $errorMessage = $_.Exception.Message }
        $raw = if (Test-Path -LiteralPath (Join-Path $reportRoot $logName)) {
            Get-Content -LiteralPath (Join-Path $reportRoot $logName) -Raw
        } else { "" }
        $hresults = @([regex]::Matches([string]$raw, '(?i)0x[0-9a-f]{8}') |
            ForEach-Object { $_.Value.ToLowerInvariant() } | Sort-Object -Unique)
        $success = $null -ne $exitCode -and $exitCode -eq 0 -and !$errorMessage
        $cause = if ($success) { "update_completed" }
            elseif ($hresults -contains "0x80072ee2") { "update_network_timeout" }
            elseif ($errorMessage) { "update_command_error" }
            else { "update_error" }
        $delay = if (!$success -and $attempt -lt 3) { 15 * $attempt } else { 0 }
        $attempts.Add([pscustomobject]@{
            Attempt = $attempt; StartedUTC = $started
            FinishedUTC = [DateTime]::UtcNow.ToString('o')
            ExitCode = $exitCode; HResults = $hresults; Cause = $cause
            Error = $errorMessage; Log = $logName; RetryDelaySeconds = $delay
        })
        ConvertTo-Json -InputObject @($attempts.ToArray()) -Depth 5 |
            Set-Content -LiteralPath (Join-Path $reportRoot "SignatureUpdateAttempts.json") -Encoding utf8
        Note "Defender update attempt $attempt/3: cause=$cause; exit=$exitCode; HRESULT=$($hresults -join ','); error=$errorMessage"
        if ($success) { return }
        if ($delay) {
            Note "Retrying security intelligence update in $delay seconds; malware scan has not started."
            Start-Sleep -Seconds $delay
        }
    }
    throw "UPDATE_FAILED: Defender security intelligence update failed after 3 attempts. Malware scan NOT_RUN; distribution remains blocked."
}
function Inventory([string[]]$Roots) {
    $files = foreach ($root in $Roots) {
        if (Test-Path -LiteralPath $root -PathType Container) {
            Get-ChildItem -LiteralPath $root -Recurse -File
        } else { Get-Item -LiteralPath $root }
    }
    foreach ($file in ($files | Sort-Object FullName -Unique)) {
        $signature = if ($file.Extension -in ".exe", ".dll", ".vst3", ".msix") {
            [string](Get-AuthenticodeSignature -LiteralPath $file.FullName).Status
        } else { "NotApplicable" }
        [pscustomobject]@{
            Path = $file.FullName
            Bytes = $file.Length
            SHA256 = (Get-FileHash -LiteralPath $file.FullName -Algorithm SHA256).Hash.ToLowerInvariant()
            Authenticode = $signature
        }
    }
}
Note "RavenForge Luthier Intelligence / Windows artifact malware inspection"
Note "Started UTC: $([DateTime]::UtcNow.ToString('o'))"
$sourceRevision = (& git -C $PSScriptRoot rev-parse HEAD).Trim()
if ($LASTEXITCODE -ne 0) { throw "Cannot resolve checked-out scan source." }
Note "Source revision: $sourceRevision"
Note "Scope: local Microsoft Defender scan. Not Google Safe Browsing clearance, Store certification, or a guarantee of safety."
try {
    $roots = @($Path | ForEach-Object { (Resolve-Path -LiteralPath $_).Path })
    if (!$roots.Count) { throw "No scan inputs." }
    foreach ($root in $roots) {
        if ($reportRoot -eq $root -or $reportRoot.StartsWith($root.TrimEnd('\') + '\', [StringComparison]::OrdinalIgnoreCase)) {
            throw "Reports must be outside the scan inputs."
        }
    }
    $before = @(Inventory $roots)
    if (!$before.Count) { throw "Scan inputs contain no files." }
    $before | ConvertTo-Json -Depth 4 | Set-Content -LiteralPath (Join-Path $reportRoot "FileInventory.json") -Encoding utf8
    Note "Input files: $($before.Count); SHA256 and signature status recorded in FileInventory.json."
    $platform = Join-Path $env:ProgramData "Microsoft/Windows Defender/Platform"
    $candidates = @(Get-ChildItem -LiteralPath $platform -Filter MpCmdRun.exe -Recurse -File -ErrorAction SilentlyContinue | Sort-Object FullName -Descending)
    $script:mpCmdRun = if ($candidates.Count) { $candidates[0].FullName } else { Join-Path $env:ProgramFiles "Windows Defender/MpCmdRun.exe" }
    if (!(Test-Path -LiteralPath $mpCmdRun)) { throw "Microsoft Defender command-line scanner is unavailable." }
    $service = Get-Service WinDefend
    if ($service.Status -ne "Running") { Start-Service WinDefend }
    $status = Get-MpComputerStatus
    if (!$status.AMServiceEnabled) { throw "Microsoft Defender scanning service is not active." }
    # Hosted runner images can disable archive/script scans for build speed.
    # Enable those scans; never disable security or add exclusions here.
    Set-MpPreference -DisableArchiveScanning $false -DisableScriptScanning $false -PUAProtection Enabled
    $preferences = Get-MpPreference
    if ($preferences.DisableArchiveScanning -or $preferences.DisableScriptScanning -or $preferences.PUAProtection -ne 1) {
        throw "Required scan settings did not take effect."
    }
    Update-DefenderIntelligence
    $status = Get-MpComputerStatus
    $status | Select-Object AMEngineVersion, AMProductVersion, AMServiceEnabled, AMRunningMode,
        AntivirusSignatureVersion, AntivirusSignatureLastUpdated, RealTimeProtectionEnabled |
        ConvertTo-Json | Set-Content -LiteralPath (Join-Path $reportRoot "DefenderStatus.json") -Encoding utf8
    if (!$status.AMServiceEnabled -or !$status.AMEngineVersion -or !$status.AntivirusSignatureVersion -or
        ([DateTime]::UtcNow - $status.AntivirusSignatureLastUpdated.ToUniversalTime()).TotalDays -gt 2) {
        throw "DEFINITIONS_INVALID: Defender is not ready with current security intelligence. Malware scan NOT_RUN; distribution remains blocked."
    }
    Note "Engine: $($status.AMEngineVersion); signatures: $($status.AntivirusSignatureVersion); updated: $($status.AntivirusSignatureLastUpdated.ToUniversalTime().ToString('o'))"
    Note "Manual custom scans use -DisableRemediation: ignore path exclusions, scan archives, report detections without altering input files."
    Note "Runner cloud reporting mode: $($preferences.MAPSReporting); automatic sample submission: $($preferences.SubmitSamplesConsent). These settings are not changed."
    $number = 0
    $failures = 0
    foreach ($root in $roots) {
        ++$number
        $result = Defender-Command @("-Scan", "-ScanType", "3", "-File", $root, "-DisableRemediation") "Scan-$number.log"
        if ($result -ne 0) {
            ++$failures
            Note "BLOCKED: scan exit $result for $root. See Scan-$number.log for detection/error details."
        } else { Note "PASS: Defender completed scan with no detections: $root" }
    }
    $after = @(Inventory $roots)
    $difference = Compare-Object $before $after -Property Path, Bytes, SHA256
    if ($difference) { throw "Files changed or disappeared during the scan; the result cannot approve these artifacts." }
    if ($failures) { throw "$failures scan(s) reported detections or errors. Distribution remains blocked." }
    Note "PASS: all input hashes unchanged after scanning."
    Note "PASS: completed local Defender inspection. Unsigned files remain unsigned and browser warnings may remain."
} catch {
    Note "FAIL: $($_.Exception.Message)"
    throw
} finally {
    Note "Finished UTC: $([DateTime]::UtcNow.ToString('o'))"
    if ($env:GITHUB_STEP_SUMMARY) {
        "### Windows artifact inspection`n`n``````text`n$($lines -join "`n")`n```````n" |
            Add-Content -LiteralPath $env:GITHUB_STEP_SUMMARY -Encoding utf8
    }
}

param(
    [string]$Package = "",
    [string]$OutputDirectory = "build/msix-verification"
)
$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest
# Install/remove tests are confined to a disposable CI runner, never a customer's PC.
if ($env:GITHUB_ACTIONS -ne "true") { throw "MSIX install verification must run in disposable GitHub Actions Windows CI." }
$identityJson = & python (Join-Path $PSScriptRoot "chimera_version.py")
if ($LASTEXITCODE -ne 0) { throw "Cannot resolve the source product version." }
$buildIdentity = $identityJson | ConvertFrom-Json
if (!$Package) { $Package = "dist/msix/Chimera-$($buildIdentity.product_version).0-x64-review-unsigned.msix" }
$packagePath = (Resolve-Path -LiteralPath $Package).Path
New-Item -ItemType Directory -Path $OutputDirectory -Force | Out-Null
$outputPath = (Resolve-Path -LiteralPath $OutputDirectory).Path
$report = Join-Path $outputPath "MSIXVerification.txt"
"MSIX verification; Windows $([Environment]::OSVersion.Version); Store certification is not performed by this test." | Set-Content -LiteralPath $report -Encoding UTF8
function Pass([string]$Message) {
    $line = "PASS: $Message"
    Add-Content -LiteralPath $report -Value $line -Encoding UTF8
    Write-Host $line
}
$makeAppx = Get-ChildItem -Path "${env:ProgramFiles(x86)}/Windows Kits/10/bin/*/x64/makeappx.exe" |
    Sort-Object FullName -Descending | Select-Object -First 1 -ExpandProperty FullName
$unpacked = Join-Path $outputPath ("payload-" + [guid]::NewGuid().ToString("N"))
$testName = "RavenForge.Chimera.CI" + $env:GITHUB_RUN_ID
$installed = $null
$launched = $null
$marker = $null
try {
    $expectedHash = ((Get-Content -LiteralPath ($packagePath + ".sha256.txt") -Raw).Trim() -split '\s+')[0]
    if ((Get-FileHash -LiteralPath $packagePath -Algorithm SHA256).Hash.ToLowerInvariant() -ne $expectedHash) { throw "MSIX checksum mismatch." }
    & $makeAppx unpack /p $packagePath /d $unpacked
    if ($LASTEXITCODE -ne 0) { throw "MakeAppx could not unpack/validate the MSIX." }
    [xml]$manifest = Get-Content -LiteralPath "$unpacked/AppxManifest.xml" -Raw
    if ($manifest.Package.Properties.PublisherDisplayName -cne "RavenForge Luthier Intelligence" -or
        $manifest.Package.Identity.ProcessorArchitecture -ne "x64") { throw "MSIX publisher/architecture mismatch." }
    if ($manifest.Package.Applications.Application.GetAttribute("RuntimeBehavior", "http://schemas.microsoft.com/appx/manifest/uap/windows10/10") -ne "win32App") {
        throw "IR/user preferences must not be silently moved to virtualized AppData."
    }
    if (@(Get-ChildItem -LiteralPath $unpacked -Recurse -File | Where-Object { $_.Extension -in ".vst3", ".nam", ".wav" }).Count) {
        throw "Standalone MSIX must not imply global VST3 registration or bundle private captures."
    }
    $sourceExe = "dist/SpectralForge-Chimera-$($buildIdentity.version)-win64/Standalone/SpectralForge Chimera.exe"
    if ((Get-FileHash -LiteralPath "$unpacked/App/SpectralForge Chimera.exe").Hash -ne (Get-FileHash -LiteralPath $sourceExe).Hash) {
        throw "Packaged app differs from the DSP/UI-validated standalone."
    }
    Pass "SHA256, MakeAppx unpack, RavenForge identity, x64 architecture and exact validated application payload"
    Pass "Full-trust Win32 manifest; no virtualized VST3 install or private NAM/IR files"

    $blocked = $false
    try { & "$PSScriptRoot/Build-WindowsMSIX.ps1" -Mode Store }
    catch { if ($_.Exception.Message -notmatch "real Partner Center identity JSON") { throw }; $blocked = $true }
    if (!$blocked) { throw "Store packaging accepted an absent account identity." }
    $blocked = $false
    try { & "$PSScriptRoot/Build-WindowsMSIX.ps1" -Mode Signed -CertificateThumbprint "" }
    catch { if ($_.Exception.Message -notmatch "verified public code-signing certificate") { throw }; $blocked = $true }
    if (!$blocked) { throw "Direct distribution accepted an absent signing certificate." }
    Pass "Store and signed release modes reject missing identity instead of creating a misleading release"

    # Microsoft-documented Windows 11+ unsigned test identity. This changed package
    # is CI-only, is not uploaded, and cannot impersonate the release identity.
    if (Get-AppxPackage -Name $testName) { throw "An existing test package must not be overwritten." }
    $manifest.Package.Identity.SetAttribute("Name", $testName)
    $manifest.Package.Identity.SetAttribute("Publisher", "CN=RavenForge Luthier Intelligence, OID.2.25.311729368913984317654407730594956997722=1")
    $manifest.Save("$unpacked/AppxManifest.xml")
    foreach ($file in @("AppxBlockMap.xml", "[Content_Types].xml", "AppxSignature.p7x")) {
        $generated = Join-Path $unpacked $file
        if (Test-Path -LiteralPath $generated) { Remove-Item -LiteralPath $generated -Force }
    }
    $testPackage = Join-Path $outputPath "CI-only-unsigned.msix"
    & $makeAppx pack /d $unpacked /p $testPackage /h SHA256 /o
    if ($LASTEXITCODE -ne 0) { throw "CI-only package could not be created." }
    Add-AppxPackage -Path $testPackage -AllowUnsigned
    $installed = Get-AppxPackage -Name $testName
    if (!$installed -or $installed.Status -ne "Ok") { throw "MSIX deployment did not register a healthy package." }
    $aumid = $installed.PackageFamilyName + "!Chimera"
    $installedExe = Join-Path $installed.InstallLocation "App/SpectralForge Chimera.exe"
    Start-Process explorer.exe -ArgumentList "shell:AppsFolder\$aumid" | Out-Null
    for ($attempt=0; $attempt -lt 60; ++$attempt) {
        $launched = Get-Process -Name "SpectralForge Chimera" -ErrorAction SilentlyContinue |
            Where-Object { $_.Path -eq $installedExe -and $_.MainWindowHandle -ne 0 } | Select-Object -First 1
        if ($launched) { break }
        Start-Sleep -Milliseconds 500
    }
    if (!$launched -or $launched.MainWindowTitle -notlike "*Chimera*") { throw "Package activation did not open the actual Chimera window." }
    Pass "CI-isolated unsigned identity installs and launches the real application through its registered AppUserModelID"
    $launched.CloseMainWindow() | Out-Null
    if (!$launched.WaitForExit(5000)) { $launched.Kill(); $launched.WaitForExit() }
    $launched = $null

    $external = Join-Path ([Environment]::GetFolderPath("ApplicationData")) "SpectralForge/Chimera/IRs"
    New-Item -ItemType Directory -Path $external -Force | Out-Null
    $marker = Join-Path $external ("msix-preserve-" + [guid]::NewGuid().ToString("N") + ".txt")
    "external user IR library marker" | Set-Content -LiteralPath $marker
    Remove-AppxPackage -Package $installed.PackageFullName
    $installed = $null
    if (Get-AppxPackage -Name $testName) { throw "MSIX uninstall left the test registration behind." }
    if (!(Test-Path -LiteralPath $marker)) { throw "MSIX uninstall removed external user-library data." }
    Pass "Uninstall removes only the CI package registration and preserves the external user IR library"
} catch {
    "FAIL: $($_.Exception.Message)" | Add-Content -LiteralPath $report -Encoding UTF8
    throw
} finally {
    if ($launched -and !$launched.HasExited) { $launched.Kill() }
    $leftover = Get-AppxPackage -Name $testName -ErrorAction SilentlyContinue
    if ($leftover) { Remove-AppxPackage -Package $leftover.PackageFullName }
    if ($marker -and (Test-Path -LiteralPath $marker)) { Remove-Item -LiteralPath $marker -Force }
    if (Test-Path -LiteralPath $unpacked) { Remove-Item -LiteralPath $unpacked -Recurse -Force }
    $testPackage = Join-Path $outputPath "CI-only-unsigned.msix"
    if (Test-Path -LiteralPath $testPackage) { Remove-Item -LiteralPath $testPackage -Force }
}

